import json

# Extract the table data from the JSON
with open('/app/resources/treasury_bulletin_1956_08.json', 'r') as f:
    data = json.load(f)

# Find elements with "20 years and after" content
for elem in data['document']['elements']:
    if elem.get('type') == 'table':
        if 'content' in elem and elem['content']:
            if '20 years and after' in str(elem['content']):
                print(json.dumps(elem, indent=2))
                break
EOF

